import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`smb-grants`,heroTitle:`Find grants for your business in minutes`,heroSubtitle:`Perplexity Computer searches federal, state, and local grant databases, filters by your eligibility, and delivers a matched grants report — automatically.`,inputUrlCta:`Find my grants`,inputUrlPlaceholder:`e.g. bakery in Austin, $500K revenue`,inputUrlPrefill:`Take the following business description: {url}. Use it to extract the business type, industry, location (city, state), revenue range, employee count, and any other eligibility details. Then: (1) Search SBA.gov, Grants.gov, and state and local economic development agency grant databases for small business grants matching this profile. (2) Filter results by eligibility — business type, industry, location, revenue, minority/veteran/women-owned status if mentioned, and any other qualifying criteria. (3) For each matched grant, extract the grant name, awarding agency, award amount or range, application deadline, key requirements, and a direct link to the application page. (4) Flag grants with deadlines in the next 60 days as urgent. (5) Deliver a structured grants report organized by funding level (federal, state, local), sorted by deadline, with a summary table showing grant name, amount, deadline, and match strength — plus a quick-start checklist of documents typically required for the top 5 matches.`,heroOverlaySteps:[`Searching SBA.gov, Grants.gov, and state databases for matching grants`,`Filtering grants by your business type, location, and revenue eligibility`,`Extracting award amounts, deadlines, requirements, and application links`,`Matched grants report with deadlines and application checklist — ready to review`],generatingSteps:[`Analyzing {url} to extract business type, location, and eligibility details`,`Designing an agent to search federal, state, and local grant databases`,`Configuring eligibility filters and deadline tracking across SBA.gov and Grants.gov`,`Setting up matched grants report with amounts, deadlines, and application links`],featureSectionTitle:`From business profile to grant matches`,featureCardTitles:[`Connects to your business stack`,`Outputs you can act on`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Google Sheets, Google Drive, Gmail, Notion — Computer exports your grants report, tracks deadlines, and sends reminders in the tools you already use.`,`Matched grants ranked by fit. Award amounts and deadlines. Eligibility requirements. Direct application links. Document checklist for your top matches.`],capabilitySectionTitle:`Your grants researcher, on autopilot`,capabilitySectionSubtitle:`Describe your business, step away, get a matched grants report.`,capabilityCards:[{title:`Multi-Database Search`,description:`Computer can search SBA.gov, Grants.gov, and state and local economic development databases simultaneously — so you never miss a funding opportunity.`},{title:`Eligibility Filtering`,description:`Computer can filter grants by business type, industry, location, revenue, and ownership status — returning only grants you actually qualify for.`},{title:`Deadline Prioritization`,description:`Computer can flag grants closing in the next 60 days, sort by deadline urgency, and surface fast-approaching opportunities you'd otherwise miss.`},{title:`Connect Your Tools`,description:`Computer can export to Google Sheets, Google Drive, Gmail, and Notion — build workflows that track grant deadlines and application progress in one place.`},{title:`Knows Your Business`,description:`Computer can remember your business profile, past grant searches, and application history across sessions — so every search builds on what you've already done.`},{title:`New Grant Alerts`,description:`Computer can monitor grant databases weekly — and alert you when new grants matching your profile are posted or deadlines are approaching.`}]});export{t as default};
